"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Portal } from "../lib/portal";
import { Icon, type IconName } from "../icons/icon";

export type ToastTone = "neutral" | "accent" | "green" | "amber" | "red" | "blue";

export interface ToastOptions {
  title: React.ReactNode;
  description?: React.ReactNode;
  tone?: ToastTone;
  /** Duur in ms; 0 blijft staan tot de gebruiker sluit. */
  duration?: number;
  icon?: React.ReactNode;
  action?: { label: string; onClick: () => void };
}

export interface ToastItem extends ToastOptions {
  id: string;
  /** Staat op de uitgaande animatie te wachten voor hij uit de lijst gaat. */
  leaving?: boolean;
}

interface ToastContextValue {
  toasts: ToastItem[];
  push: (options: ToastOptions) => string;
  dismiss: (id: string) => void;
}

const ToastContext = React.createContext<ToastContextValue | null>(null);

export interface ToastProviderProps {
  children: React.ReactNode;
  /** Maximum aantal zichtbare meldingen. */
  max?: number;
  position?: "bottom-right" | "bottom-left" | "top-right" | "top-left" | "bottom-center" | "top-center";
  /** Standaardduur in ms. */
  duration?: number;
}

/** ToastProvider — zet dit één keer rond je app. */
export function ToastProvider({
  children,
  max = 4,
  position = "bottom-right",
  duration = 4200,
}: ToastProviderProps) {
  const [toasts, setToasts] = React.useState<ToastItem[]>([]);
  const timers = React.useRef(new Map<string, number>());

  const dismiss = React.useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (timer) window.clearTimeout(timer);

    // Eerst markeren als vertrekkend; pas als de uitgaande animatie klaar is
    // verdwijnt de melding echt uit de lijst.
    setToasts((prev) => prev.map((toast) => (toast.id === id ? { ...toast, leaving: true } : toast)));
    timers.current.set(
      id,
      window.setTimeout(() => {
        setToasts((prev) => prev.filter((toast) => toast.id !== id));
        timers.current.delete(id);
      }, 190)
    );
  }, []);

  const push = React.useCallback(
    (options: ToastOptions) => {
      const id = `lui-toast-${Math.random().toString(36).slice(2, 10)}`;
      setToasts((prev) => [...prev, { ...options, id }].slice(-max));
      const life = options.duration ?? duration;
      if (life > 0) {
        timers.current.set(id, window.setTimeout(() => dismiss(id), life));
      }
      return id;
    },
    [max, duration, dismiss]
  );

  React.useEffect(() => {
    const map = timers.current;
    return () => map.forEach((timer) => window.clearTimeout(timer));
  }, []);

  return (
    <ToastContext.Provider value={{ toasts, push, dismiss }}>
      {children}
      <Toaster position={position} />
    </ToastContext.Provider>
  );
}

const TONE_ICON: Record<ToastTone, IconName> = {
  neutral: "info",
  accent: "sparkles",
  green: "checkCircle",
  amber: "alert",
  red: "alertCircle",
  blue: "info",
};

/** Toaster — rendert de stapel meldingen. Wordt door ToastProvider geplaatst. */
export function Toaster({ position = "bottom-right" }: { position?: ToastProviderProps["position"] }) {
  const context = React.useContext(ToastContext);
  if (!context || context.toasts.length === 0) return null;

  return (
    <Portal>
      <div className={cn("lui-toaster", `lui-toaster-${position}`)} role="region" aria-label="Meldingen">
        {context.toasts.map((toast) => {
          const tone = toast.tone ?? "neutral";
          return (
            <div
              key={toast.id}
              data-state={toast.leaving ? "closed" : "open"}
              className={cn("lui-toast", `lui-toast-${tone}`)}
              role="status"
            >
              <span className="lui-toast-icon">
                {toast.icon ?? <Icon name={TONE_ICON[tone]} size={15} />}
              </span>
              <div className="lui-toast-body">
                <div className="lui-toast-title">{toast.title}</div>
                {toast.description && <div className="lui-toast-description">{toast.description}</div>}
              </div>
              {toast.action && (
                <button
                  type="button"
                  className="lui-toast-action"
                  onClick={() => {
                    toast.action?.onClick();
                    context.dismiss(toast.id);
                  }}
                >
                  {toast.action.label}
                </button>
              )}
              <button
                type="button"
                className="lui-toast-close"
                aria-label="Sluiten"
                onClick={() => context.dismiss(toast.id)}
              >
                <Icon name="x" size={14} />
              </button>
            </div>
          );
        })}
      </div>
    </Portal>
  );
}

export interface ToastApi {
  (options: ToastOptions): string;
  success: (title: React.ReactNode, options?: Omit<ToastOptions, "title" | "tone">) => string;
  error: (title: React.ReactNode, options?: Omit<ToastOptions, "title" | "tone">) => string;
  warning: (title: React.ReactNode, options?: Omit<ToastOptions, "title" | "tone">) => string;
  info: (title: React.ReactNode, options?: Omit<ToastOptions, "title" | "tone">) => string;
  dismiss: (id: string) => void;
}

/** useToast — meldingen tonen vanuit elk component onder de ToastProvider. */
export function useToast(): ToastApi {
  const context = React.useContext(ToastContext);
  if (!context) throw new Error("useToast() vereist een <ToastProvider> hoger in de boom.");

  return React.useMemo(() => {
    const api = ((options: ToastOptions) => context.push(options)) as ToastApi;
    api.success = (title, options) => context.push({ ...options, title, tone: "green" });
    api.error = (title, options) => context.push({ ...options, title, tone: "red" });
    api.warning = (title, options) => context.push({ ...options, title, tone: "amber" });
    api.info = (title, options) => context.push({ ...options, title, tone: "blue" });
    api.dismiss = context.dismiss;
    return api;
  }, [context]);
}

/* ============================ Toast ============================ */
.lui-toaster {
  position: fixed; z-index: var(--z-toast);
  display: flex; flex-direction: column; gap: 10px;
  pointer-events: none; max-width: min(380px, calc(100vw - 24px));
}
.lui-toaster-bottom-right { bottom: 24px; right: 24px; }
.lui-toaster-bottom-left { bottom: 24px; left: 24px; }
.lui-toaster-top-right { top: 24px; right: 24px; flex-direction: column-reverse; }
.lui-toaster-top-left { top: 24px; left: 24px; flex-direction: column-reverse; }
.lui-toaster-bottom-center { bottom: 24px; left: 50%; transform: translateX(-50%); }
.lui-toaster-top-center { top: 24px; left: 50%; transform: translateX(-50%); flex-direction: column-reverse; }

.lui-toast {
  --lui-toast-color: var(--text-3);
  pointer-events: auto; position: relative;
  display: flex; align-items: flex-start; gap: 11px;
  min-width: 280px; padding: 13px 14px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-md); box-shadow: var(--sh-lg);
  animation: lui-toast-in var(--dur-slow) var(--ease-pop) both;
}
@keyframes lui-toast-in {
  from { opacity: 0; transform: translateY(14px) scale(.96); }
  to { opacity: 1; transform: none; }
}

.lui-toast-accent { --lui-toast-color: var(--accent); }
.lui-toast-green { --lui-toast-color: var(--green); }
.lui-toast-amber { --lui-toast-color: var(--amber); }
.lui-toast-red { --lui-toast-color: var(--red); }
.lui-toast-blue { --lui-toast-color: var(--blue); }

.lui-toast-icon {
  display: grid; place-items: center; flex: none;
  width: 26px; height: 26px; border-radius: 7px;
  color: var(--lui-toast-color);
  background: color-mix(in srgb, var(--lui-toast-color) 14%, transparent);
}
.lui-toast-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; padding-top: 2px; }
.lui-toast-title { font-size: 13.5px; font-weight: 600; color: var(--text); line-height: 1.35; }
.lui-toast-description { font-size: var(--fs-sm); color: var(--text-2); line-height: 1.45; }
.lui-toast-action {
  flex: none; align-self: center; border: none; background: transparent;
  color: var(--accent); font: inherit; font-size: 13px; font-weight: 650;
  cursor: pointer; padding: 4px 6px; border-radius: var(--r-xs);
}
.lui-toast-action:hover { background: var(--accent-tint); }
.lui-toast-close {
  flex: none; display: grid; place-items: center; width: 22px; height: 22px;
  border: none; background: transparent; color: var(--text-3);
  border-radius: var(--r-xs); cursor: pointer;
}
.lui-toast-close:hover { background: var(--surface-3); color: var(--text); }

@media (max-width: 560px) {
  .lui-toaster { left: 12px; right: 12px; max-width: none; transform: none; }
  .lui-toaster-bottom-right, .lui-toaster-bottom-left, .lui-toaster-bottom-center { bottom: 12px; }
  .lui-toaster-top-right, .lui-toaster-top-left, .lui-toaster-top-center { top: 12px; }
  .lui-toast { min-width: 0; }
}

/* ---------- Sluiten ---------- */
.lui-toast[data-state="closed"] { animation: lui-toast-out .18s var(--ease) both; }

@keyframes lui-toast-out {
  from { opacity: 1; transform: none; max-height: 200px; }
  to { opacity: 0; transform: translateX(12px) scale(.97); max-height: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .lui-toast, .lui-toast[data-state="closed"] { animation-duration: .01ms; }
}
